function character(){return {gender:pick(genders),age:18+Math.floor(Math.random()*30),profession:pick(jobs),hobby:pick(hobbies),trait:pick(traits),health:pick(healthStates),skill:pick(skills),phobia:pick(phobias),bag:pick(bags),secret:pick(['має прихований запас їжі','боїться темряви','колись працював у лабораторії','вміє лагодити радіо','не довіряє незнайомцям','знає маршрут до старого сховища'])}}
function publicState(room,sid){return {code:room.code,hostId:room.hostId,meId:sid,maxPlayers:room.maxPlayers,capacity:room.capacity,players:[...room.players.values()].map(p=>({id:p.id,name:p.name,eliminated:p.eliminated,character:p.character})),phase:room.phase,catastrophe:room.catastrophe,bunker:room.bunker,status:room.status,myVote:room.votes.has(sid),votesCount:room.votes.size,round:room.round,isHost:room.hostId===sid};}
function broadcast(room){for(const p of room.players.values())io.to(p.id).emit('state',publicState(room,p.id))}
function response(socket,room,cb){if(cb)cb({ok:true,state:publicState(room,socket.id)})}
function roomFor(socket){const code=socket.data.room;return code&&rooms.get(code)}
function codeGen(){let c;do{c=String(Math.floor(100000+Math.random()*900000))}while(rooms.has(c));return c}
io.on('connection',socket=>{
socket.on('createRoom',(d,cb)=>{const name=String(d.name||'').trim().slice(0,20);const maxPlayers=Math.max(1,Math.min(20,Number(d.maxPlayers)||1));const capacity=Math.max(1,Math.min(maxPlayers-1,Number(d.capacity)||1));if(!name)return cb?.({ok:false,error:'Введи ім’я.'});const code=codeGen();const room={code,hostId:socket.id,maxPlayers,capacity,players:new Map(),phase:'lobby',catastrophe:'',status:'Очікуємо на гравців.',votes:new Map(),round:0};room.players.set(socket.id,{id:socket.id,name,eliminated:false,character:''});rooms.set(code,room);socket.data.room=code;response(socket,room,cb);broadcast(room)});
socket.on('joinRoom',(d,cb)=>{const name=String(d.name||'').trim().slice(0,20),code=String(d.code||'').replace(/\\D/g,'').trim();const room=rooms.get(code);if(!name)return cb?.({ok:false,error:'Введи ім’я.'});if(!room){console.log('Join failed: room not found',code,'active rooms:',[...rooms.keys()]);return cb?.({ok:false,error:'Кімнату з таким кодом не знайдено. Переконайся, що ви відкрили однакове посилання гри, а ведучий ще перебуває в кімнаті. Якщо так — створи нову кімнату й спробуйте ще раз.'});}if(room.phase!=='lobby')return cb?.({ok:false,error:'Гра вже почалася.'});if(room.players.size>=room.maxPlayers)return cb?.({ok:false,error:'У кімнаті немає вільних місць.'});room.players.set(socket.id,{id:socket.id,name,eliminated:false,character:''});socket.data.room=code;response(socket,room,cb);broadcast(room)});
socket.on('startGame',(d,cb)=>{const r=roomFor(socket);if(!r||r.hostId!==socket.id)return cb?.({ok:false,error:'Тільки ведучий може почати гру.'});if(r.players.size<1)return cb?.({ok:false,error:'Потрібен щонайменше 1 гравець.'});if(r.players.size!==r.maxPlayers)return cb?.({ok:false,error:'Дочекайся всіх гравців.'});const c=pick(catastrophes);r.catastrophe=c[0]+'\n\n'+c[1];r.bunker=null;r.players.forEach(p=>p.character=character());r.phase='catastrophe';r.round=1;r.votes.clear();r.status='Катастрофу визначено. Натисніть «Далі», щоб дізнатися характеристики бункера.';broadcast(r);cb?.({ok:true})});
socket.on('showBunker',(d,cb)=>{const r=roomFor(socket);if(!r||r.hostId!==socket.id)return cb?.({ok:false,error:'Тільки ведучий може продовжити.'});if(r.phase!=='catastrophe')return cb?.({ok:false,error:'Зараз цей крок недоступний.'});r.bunker=generateBunker();r.phase='bunker';r.status='Характеристики бункера визначено.';broadcast(r);cb?.({ok:true})});
socket.on('startVoting',(d,cb)=>{const r=roomFor(socket);if(!r||r.hostId!==socket.id)return cb?.({ok:false,error:'Тільки ведучий може продовжити.'});if(r.phase!=='bunker')return cb?.({ok:false,error:'Спочатку відкрий характеристики бункера.'});r.phase='voting';r.status='Раунд 1. Обговоріть персонажів і проголосуйте, кого виключити.';broadcast(r);cb?.({ok:true})});
socket.on('setCapacity',(d,cb)=>{const r=roomFor(socket);if(!r||r.hostId!==socket.id)return cb?.({ok:false,error:'Лише ведучий може змінювати налаштування.'});if(r.phase!=='lobby')return cb?.({ok:false,error:'Місця можна змінювати лише до початку гри.'});const capacity=Number(d.capacity);if(!Number.isInteger(capacity)||capacity<1||capacity>=r.maxPlayers)return cb?.({ok:false,error:'Введи кількість від 1 до '+(r.maxPlayers-1)+'.'});r.capacity=capacity;r.status='Ведучий змінив кількість місць у бункері: '+capacity+'.';broadcast(r);cb?.({ok:true})});
socket.on('rerollCatastrophe',(d,cb)=>{const r=roomFor(socket);if(!r||r.hostId!==socket.id)return cb?.({ok:false,error:'Лише ведучий може керувати катастрофою.'});if(r.phase==='lobby'||r.phase==='finished')return cb?.({ok:false,error:'Катастрофу можна змінити лише під час активної гри.'});const c=pick(catastrophes);r.catastrophe=c[0]+'\\n\\n'+c[1];r.status='Ведучий випадково змінив катастрофу.';broadcast(r);cb?.({ok:true})});
socket.on('endGame',(d,cb)=>{const r=roomFor(socket);if(!r||r.hostId!==socket.id)return cb?.({ok:false,error:'Лише ведучий може завершити гру.'});r.phase='finished';r.status='Гру завершив ведучий.';broadcast(r);cb?.({ok:true})});
socket.on('vote',(d,cb)=>{const r=roomFor(socket);if(!r||r.phase!=='voting')return cb?.({ok:false,error:'Зараз голосування недоступне.'});const voter=r.players.get(socket.id),target=r.players.get(d.targetId);if(!voter||voter.eliminated)return cb?.({ok:false,error:'Ти більше не можеш голосувати.'});if(!target||target.eliminated||target.id===socket.id)return cb?.({ok:false,error:'Обери доступного іншого гравця.'});if(r.votes.has(socket.id))return cb?.({ok:false,error:'Ти вже проголосував.'});r.votes.set(socket.id,target.id);if(r.votes.size>= [...r.players.values()].filter(p=>!p.eliminated).length){const tally={};for(const id of r.votes.values())tally[id]=(tally[id]||0)+1;const max=Math.max(...Object.values(tally));const tied=Object.keys(tally).filter(id=>tally[id]===max);const kicked=pick(tied);r.players.get(kicked).eliminated=true;r.status='Голосування завершено. Виключено: '+r.players.get(kicked).name+'. Місць у бункері: '+r.capacity+'.';r.votes.clear();r.round++;if([...r.players.values()].filter(p=>!p.eliminated).length<=r.capacity){r.phase='finished';r.status+=' Переможці: '+[...r.players.values()].filter(p=>!p.eliminated).map(p=>p.name).join(', ')+'. Гру завершено!'}else r.phase='roundEnd';}else r.status='Проголосувало: '+r.votes.size+'. Очікуємо інших.';broadcast(r);cb?.({ok:true})});
socket.on('nextRound',(d,cb)=>{const r=roomFor(socket);if(!r||r.hostId!==socket.id)return cb?.({ok:false,error:'Тільки ведучий може продовжити.'});if(r.phase!=='roundEnd')return cb?.({ok:false,error:'Зараз не можна почати наступний раунд.'});r.phase='voting';r.votes.clear();r.status='Раунд '+r.round+'. Обговоріть і проголосуйте.';broadcast(r);cb?.({ok:true})});
socket.on('kick',(d,cb)=>{const r=roomFor(socket);if(!r||r.hostId!==socket.id)return cb?.({ok:false,error:'Тільки ведучий може виганяти гравців.'});if(d.targetId===r.hostId)return cb?.({ok:false,error:'Не можна вигнати самого себе.'});const p=r.players.get(d.targetId);if(!p)return cb?.({ok:false,error:'Гравця не знайдено.'});io.to(p.id).emit('kicked');io.sockets.sockets.get(p.id)?.leave(r.code);r.players.delete(p.id);r.votes.delete(p.id);for(const [v,t] of r.votes)if(t===p.id)r.votes.delete(v);if(r.players.size===0)rooms.delete(r.code);else{if(r.hostId===p.id)r.hostId=[...r.players.keys()][0];broadcast(r)}cb?.({ok:true})});
socket.on('leaveRoom',()=>leave(socket));
socket.on('disconnect',()=>leave(socket));
function leave(s){
  const r=roomFor(s);
  if(!r)return;
  if(r.hostId===s.id){
    for(const p of r.players.values()){
      if(p.id!==s.id){
        io.to(p.id).emit('roomClosed');
        const other=io.sockets.sockets.get(p.id);
        if(other){other.data.room=null;other.leave(r.code);}
      }
    }
    rooms.delete(r.code);
    s.data.room=null;
    return;
  }
  r.players.delete(s.id);
  r.votes.delete(s.id);
  for(const [v,t] of r.votes)if(t===s.id)r.votes.delete(v);
  if(!r.players.size)rooms.delete(r.code);
  else broadcast(r);
  s.data.room=null;
}
});
